import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"MCP 도구","description":"","frontmatter":{},"headers":[],"relativePath":"ko/mcp-tools/overview.md","filePath":"ko/mcp-tools/overview.md","lastUpdated":1784903584000}'),n={name:"ko/mcp-tools/overview.md"};function a(s,t,r,i,l,p){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="mcp-도구" tabindex="-1">MCP 도구 <a class="header-anchor" href="#mcp-도구" aria-label="Permalink to &quot;MCP 도구&quot;">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>swag2mcp는 LLM 에이전트가 Model Context Protocol을 통해 API에 완전히 접근할 수 있도록 <strong>19개의 MCP 도구</strong>를 제공합니다. 이 도구들은 전체 워크플로우를 다룹니다: 사용 가능한 API 발견, spec 계층 구조 탐색, 엔드포인트 검색 및 검사, API 호출 실행, 큰 응답 작업.</p><h3 id="도구가-해결하는-문제" tabindex="-1">도구가 해결하는 문제 <a class="header-anchor" href="#도구가-해결하는-문제" aria-label="Permalink to &quot;도구가 해결하는 문제&quot;">​</a></h3><ul><li><strong>발견</strong> — LLM이 사전에 ID를 알지 못해도 spec, collection, 태그를 찾을 수 있음</li><li><strong>탐색</strong> — spec → collection → tag → endpoint의 구조화된 계층 구조로 드릴다운</li><li><strong>검색</strong> — ID가 없을 때 모든 엔드포인트에 대한 전문 검색</li><li><strong>검사</strong> — 호출 전에 전체 OpenAPI 작업 객체 얻기</li><li><strong>실행</strong> — 자동 인증으로 실제 API 호출 실행</li><li><strong>큰 응답 처리</strong> — 인라인에 맞지 않는 초과된 응답의 개요, 압축, 조각 추출</li></ul><h3 id="읽기-전용-vs-변경-가능" tabindex="-1">읽기 전용 vs 변경 가능 <a class="header-anchor" href="#읽기-전용-vs-변경-가능" aria-label="Permalink to &quot;읽기 전용 vs 변경 가능&quot;">​</a></h3><table tabindex="0"><thead><tr><th>타입</th><th>개수</th><th>도구</th></tr></thead><tbody><tr><td><strong>읽기 전용</strong></td><td>17</td><td>모든 발견, 엔드포인트, 검색, 검사, 정보, 응답 도구</td></tr><tr><td><strong>변경 가능</strong></td><td>2</td><td><code>invoke</code> (실제 HTTP 호출), <code>auth</code> (토큰 검색)</td></tr></tbody></table><p>읽기 전용 도구는 MCP 프로토콜에서 <code>ReadOnlyHint=true</code>와 <code>IdempotentHint=true</code>로 표시되어 LLM에 부작용 없이 호출해도 안전함을 알립니다.</p><h3 id="오류-처리" tabindex="-1">오류 처리 <a class="header-anchor" href="#오류-처리" aria-label="Permalink to &quot;오류 처리&quot;">​</a></h3><p>모든 도구는 머신 판독 가능 코드와 사람이 읽을 수 있는 메시지가 있는 구조화된 <code>LLMError</code> 객체로 오류를 반환합니다:</p><table tabindex="0"><thead><tr><th>오류 코드</th><th>의미</th></tr></thead><tbody><tr><td><code>validation_failed</code></td><td>잘못된 입력 (잘못된 ID 형식, 필수 필드 누락)</td></tr><tr><td><code>not_found</code></td><td>인덱스 또는 워크스페이스에서 엔티티를 찾을 수 없음</td></tr><tr><td><code>rate_limit</code></td><td>동일한 엔드포인트에 10초 내 두 번째 <code>invoke</code> 호출</td></tr><tr><td><code>invoke_error</code></td><td>HTTP 호출 실패, 다운로드 실패</td></tr><tr><td><code>auth_error</code></td><td>인증 토큰 검색 실패</td></tr><tr><td><code>config_error</code></td><td>설정 파일 로드 또는 저장 실패</td></tr><tr><td><code>parse_error</code></td><td>명세 파일 파싱 실패</td></tr></tbody></table><h2 id="카테고리" tabindex="-1">카테고리 <a class="header-anchor" href="#카테고리" aria-label="Permalink to &quot;카테고리&quot;">​</a></h2><table tabindex="0"><thead><tr><th>카테고리</th><th>도구</th><th>설명</th></tr></thead><tbody><tr><td><strong>발견</strong></td><td><code>spec_list</code>, <code>spec_by_id</code>, <code>collection_by_spec</code>, <code>collection_by_id</code>, <code>tag_by_spec</code>, <code>tag_by_collection</code>, <code>tag_by_id</code></td><td>Spec 계층 구조 탐색: spec, collection, 태그 찾기</td></tr><tr><td><strong>엔드포인트</strong></td><td><code>endpoint_by_spec</code>, <code>endpoint_by_collection</code>, <code>endpoint_by_tag</code>, <code>endpoint_by_id</code></td><td>계층 구조의 다양한 수준에서 엔드포인트 보기</td></tr><tr><td><strong>실행</strong></td><td><code>search</code>, <code>inspect</code>, <code>invoke</code></td><td>검색, 전체 계약 검사, API 호출</td></tr><tr><td><strong>유틸리티</strong></td><td><code>auth</code>, <code>info</code>, <code>response_outline</code>, <code>response_compress</code>, <code>response_slice</code></td><td>인증 토큰, 런타임 정보, 큰 응답 처리</td></tr><tr><td><strong>스킬</strong></td><td><a href="/mcp-tools/skills">포맷팅 가이드</a></td><td>도구 응답 표시 방식 사용자 정의</td></tr></tbody></table><h2 id="전체-목록" tabindex="-1">전체 목록 <a class="header-anchor" href="#전체-목록" aria-label="Permalink to &quot;전체 목록&quot;">​</a></h2><table tabindex="0"><thead><tr><th>도구</th><th>설명</th></tr></thead><tbody><tr><td><code>spec_list</code></td><td>워크스페이스의 모든 API 명세 나열</td></tr><tr><td><code>spec_by_id</code></td><td>collection이 포함된 상세 spec 정보 가져오기</td></tr><tr><td><code>collection_by_spec</code></td><td>spec 내의 collection 나열</td></tr><tr><td><code>collection_by_id</code></td><td>태그가 포함된 collection 세부 정보 가져오기</td></tr><tr><td><code>tag_by_spec</code></td><td>spec 전체의 모든 태그 나열</td></tr><tr><td><code>tag_by_collection</code></td><td>collection 내의 태그 나열</td></tr><tr><td><code>tag_by_id</code></td><td>태그 세부 정보 가져오기 (ID, 제목, 메서드 수)</td></tr><tr><td><code>endpoint_by_spec</code></td><td>spec의 모든 엔드포인트 나열</td></tr><tr><td><code>endpoint_by_collection</code></td><td>collection의 엔드포인트 나열</td></tr><tr><td><code>endpoint_by_tag</code></td><td>태그의 엔드포인트 나열</td></tr><tr><td><code>endpoint_by_id</code></td><td>빠른 엔드포인트 요약 (메서드, 경로, 요약)</td></tr><tr><td><code>search</code></td><td>모든 엔드포인트에 대한 전문 검색</td></tr><tr><td><code>inspect</code></td><td>전체 OpenAPI 작업 세부 정보 (매개변수, 스키마)</td></tr><tr><td><code>invoke</code></td><td>실제 API 호출 실행</td></tr><tr><td><code>auth</code></td><td>spec의 인증 토큰 또는 헤더 가져오기</td></tr><tr><td><code>info</code></td><td>런타임 정보 (버전, spec, 설정)</td></tr><tr><td><code>response_outline</code></td><td>큰 응답 파일의 구조적 요약</td></tr><tr><td><code>response_compress</code></td><td>큰 응답을 압축하여 인라인에 맞추기</td></tr><tr><td><code>response_slice</code></td><td>큰 응답의 조각 추출</td></tr></tbody></table><h2 id="탐색-계층-구조" tabindex="-1">탐색 계층 구조 <a class="header-anchor" href="#탐색-계층-구조" aria-label="Permalink to &quot;탐색 계층 구조&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec_list</span></span>
<span class="line"><span>  └── spec_by_id(id)</span></span>
<span class="line"><span>        └── collection_by_spec(specId)</span></span>
<span class="line"><span>              └── collection_by_id(id)</span></span>
<span class="line"><span>                    └── tag_by_collection(collectionId)</span></span>
<span class="line"><span>                          └── tag_by_id(id)</span></span>
<span class="line"><span>                                └── endpoint_by_tag(tagId)</span></span>
<span class="line"><span>                                      └── endpoint_by_id(id)</span></span>
<span class="line"><span>                                            └── inspect(endpointId)</span></span>
<span class="line"><span>                                                  └── invoke(endpointId)</span></span></code></pre></div><p>ID가 없으면 <code>search</code>를 사용하여 쿼리로 엔드포인트를 찾으세요. <code>invoke</code>가 <code>fileRef</code>를 반환하면(응답이 너무 큼) <code>response_outline</code> → <code>response_compress</code> 또는 <code>response_slice</code>를 사용하여 데이터를 탐색하세요.</p>`,18)])])}const b=d(n,[["render",a]]);export{h as __pageData,b as default};
